// Generates public/config.js at build time from environment variables.
// On Vercel, set API_BASE_URL in Project Settings -> Environment Variables
// to your deployed backend's URL (e.g. https://api.saferefhealth.com).
// Leave it unset locally to fall back to same-origin relative requests.

const fs = require("fs");
const path = require("path");

const apiBaseUrl = process.env.API_BASE_URL || "";

const contents = `// Auto-generated by scripts/generate-config.js during \`npm run build\`.
// Do not edit by hand - set API_BASE_URL in your environment instead.
window.API_BASE_URL = ${JSON.stringify(apiBaseUrl)};
`;

const outPath = path.join(__dirname, "..", "public", "config.js");
fs.writeFileSync(outPath, contents);
console.log(`[generate-config] wrote ${outPath} (API_BASE_URL="${apiBaseUrl}")`);
